window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-af75ca5dc65eb876"]={"versions": [{"id": "FIG-af75ca5dc65eb876", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Illustriert das Interaktionsmuster einer <strong>deklarativen Schnittstelle (Declarative API)</strong> im Kontext der AUTOSAR Adaptive Platform (<code>AUTOSAR_AP_TR_VSSRepresentation</code>, R24-11). Es visualisiert den Unterschied zwischen Sollwert-Vorgabe (Desired State) und physischem Istwert (Actual State) beim Zugriff auf Signalbäume der COVESA/W3C Vehicle Signal Specification (VSS) über das Vehicle Information Service Specification (VISS) Protokoll.\n</li><li><strong>Architektur-Ebene:</strong> Service- und Applikationsebene der AUTOSAR Adaptive Platform (Verbindung zwischen fahrzeuginternen/externen VISS-Clients und dem VISS-Provider/Server bzw. Adaptive Applications via ara::com/IPC).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Akteure / Lifelines:</strong>\n<ul class=\"fig-list\"><li><code>VISSClient</code>: Konsument der Fahrzeugdaten (z. B. Infotainment-Applikation, Cloud-Gateway oder AUTOSAR Adaptive Application).\n</li><li><code>VISSServer</code>: Dienstanbieter / VISS-Endpunkt im Fahrzeug, der den VSS-Signalbaum verwaltet und Mapping auf zugrunde liegende Sensoren/Aktuatoren vornimmt.\n</li></ul>\n</li><li><strong>Datenpfad / Signalidentifikator:</strong>\n<ul class=\"fig-list\"><li><code>Vehicle.Cabin.Seat.Position</code>: Standardisierter VSS-Datenpfad (Signal-Knoten im hierarchischen VSS-Baum für die Sitzposition, Datentyp i. d. R. <code>uint8</code> oder <code>percent</code>, Wertebereich hier: 0 … 100).\n</li></ul>\n</li><li><strong>Schnittstellen-Operationen (VISS Protocol Primitives):</strong>\n<ul class=\"fig-list\"><li><code>READ(&lt;path&gt;)</code>: Abfrage des aktuellen Zustands eines VSS-Datenelements.\n</li><li><code>UPDATE(&lt;path&gt;, &lt;value&gt;)</code>: Deklarative Sollwert-Setzung des Zielzustands (hier: 100).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initialer Istwert-Abruf:</strong>\n<ul class=\"fig-list\"><li><code>VISSClient</code> sendet synchrone/asynchrone Anfrage <code>READ(Vehicle.Cabin.Seat.Position)</code> an <code>VISSServer</code>.\n</li><li><code>VISSServer</code> antwortet mit dem aktuellen physischen Istwert <code>0</code>.\n</li></ul>\n</li><li><strong>Deklarative Sollwert-Vorgabe:</strong>\n<ul class=\"fig-list\"><li><code>VISSClient</code> setzt über <code>UPDATE(Vehicle.Cabin.Seat.Position, 100)</code> die gewünschte Zielposition.\n</li><li><em>Verhaltenssemantik:</em> Der Aufruf ist deklarativ (Zielzustandsdefinition), nicht imperativ (kein expliziter Steuerungsbefehl wie <code>startMotor()</code>). Die physische Verstellung benötigt Zeit (<em>&quot;Seat desired position declaratively updated. Seat takes time to move&quot;</em>).\n</li></ul>\n</li><li><strong>Physische Transition &amp; Zwischenstand:</strong>\n<ul class=\"fig-list\"><li>Der Aktor startet die Verstellung (<em>&quot;Seat starts moving&quot;</em>).\n</li><li>Nachfolgendes <code>READ(Vehicle.Cabin.Seat.Position)</code> liefert den transienten Istwert <code>40</code>.\n</li></ul>\n</li><li><strong>Zielwerterreichung (Konvergenz):</strong>\n<ul class=\"fig-list\"><li>Nach Abschluss der Verstellung liefert ein erneutes <code>READ(Vehicle.Cabin.Seat.Position)</code> den final erreichten Endwert <code>100</code>.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Semantik (Declarative vs. Imperative):</strong>\n<ul class=\"fig-list\"><li>Entwickler dürfen nach einem <code>UPDATE</code>-Aufruf nicht davon ausgehen, dass ein unmittelbar folgendes <code>READ</code> den neuen Wert liefert. <code>UPDATE</code> steuert den Sollwert (Actuator Target), während <code>READ</code> den physischen Istwert des Sensors/Aktuators spiegelt.\n</li></ul>\n</li><li><strong>Polling vs. Event-Driven (Pub/Sub):</strong>\n<ul class=\"fig-list\"><li>Das Schaubild zeigt Polling via wiederholte <code>READ</code>-Operationen. In produktiven AUTOSAR AP / VISS-Implementierungen ist für solche Übergänge vorzugsweise der Publish/Subscribe-Mechanismus (<code>SUBSCRIBE</code>/Notifications oder <code>ara::com</code>-Events) zu nutzen, um Buslast und CPU-Overhead durch zyklische Reads zu vermeiden.\n</li></ul>\n</li><li><strong>Zustandsmodellierung &amp; Timeouts:</strong>\n<ul class=\"fig-list\"><li>Applikationen müssen Latenzen, unvollständige Verfahrwege (z. B. Klemmschutz, Blockade, Abbruch) und Timeouts vorsehen. Erreicht der Istwert den deklarierten Sollwert innerhalb eines systemspezifischen Zeitfensters nicht, muss ein Fehlerzustand (z. B. via Diagnostic Event Manager / Dem oder Applikationslogik) behandelt werden.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-05f5e8fcaaf15855", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Illustriert das Interaktionsmuster einer <strong>deklarativen Schnittstelle (Declarative API)</strong> im Kontext der AUTOSAR Adaptive Platform (<code>AUTOSAR_AP_TR_VSSRepresentation</code>, R24-11). Es visualisiert den Unterschied zwischen Sollwert-Vorgabe (Desired State) und physischem Istwert (Actual State) beim Zugriff auf Signalbäume der COVESA/W3C Vehicle Signal Specification (VSS) über das Vehicle Information Service Specification (VISS) Protokoll.\n</li><li><strong>Architektur-Ebene:</strong> Service- und Applikationsebene der AUTOSAR Adaptive Platform (Verbindung zwischen fahrzeuginternen/externen VISS-Clients und dem VISS-Provider/Server bzw. Adaptive Applications via ara::com/IPC).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Akteure / Lifelines:</strong>\n<ul class=\"fig-list\"><li><code>VISSClient</code>: Konsument der Fahrzeugdaten (z. B. Infotainment-Applikation, Cloud-Gateway oder AUTOSAR Adaptive Application).\n</li><li><code>VISSServer</code>: Dienstanbieter / VISS-Endpunkt im Fahrzeug, der den VSS-Signalbaum verwaltet und Mapping auf zugrunde liegende Sensoren/Aktuatoren vornimmt.\n</li></ul>\n</li><li><strong>Datenpfad / Signalidentifikator:</strong>\n<ul class=\"fig-list\"><li><code>Vehicle.Cabin.Seat.Position</code>: Standardisierter VSS-Datenpfad (Signal-Knoten im hierarchischen VSS-Baum für die Sitzposition, Datentyp i. d. R. <code>uint8</code> oder <code>percent</code>, Wertebereich hier: 0 … 100).\n</li></ul>\n</li><li><strong>Schnittstellen-Operationen (VISS Protocol Primitives):</strong>\n<ul class=\"fig-list\"><li><code>READ(&lt;path&gt;)</code>: Abfrage des aktuellen Zustands eines VSS-Datenelements.\n</li><li><code>UPDATE(&lt;path&gt;, &lt;value&gt;)</code>: Deklarative Sollwert-Setzung des Zielzustands (hier: 100).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initialer Istwert-Abruf:</strong>\n<ul class=\"fig-list\"><li><code>VISSClient</code> sendet synchrone/asynchrone Anfrage <code>READ(Vehicle.Cabin.Seat.Position)</code> an <code>VISSServer</code>.\n</li><li><code>VISSServer</code> antwortet mit dem aktuellen physischen Istwert <code>0</code>.\n</li></ul>\n</li><li><strong>Deklarative Sollwert-Vorgabe:</strong>\n<ul class=\"fig-list\"><li><code>VISSClient</code> setzt über <code>UPDATE(Vehicle.Cabin.Seat.Position, 100)</code> die gewünschte Zielposition.\n</li><li><em>Verhaltenssemantik:</em> Der Aufruf ist deklarativ (Zielzustandsdefinition), nicht imperativ (kein expliziter Steuerungsbefehl wie <code>startMotor()</code>). Die physische Verstellung benötigt Zeit (<em>&quot;Seat desired position declaratively updated. Seat takes time to move&quot;</em>).\n</li></ul>\n</li><li><strong>Physische Transition &amp; Zwischenstand:</strong>\n<ul class=\"fig-list\"><li>Der Aktor startet die Verstellung (<em>&quot;Seat starts moving&quot;</em>).\n</li><li>Nachfolgendes <code>READ(Vehicle.Cabin.Seat.Position)</code> liefert den transienten Istwert <code>40</code>.\n</li></ul>\n</li><li><strong>Zielwerterreichung (Konvergenz):</strong>\n<ul class=\"fig-list\"><li>Nach Abschluss der Verstellung liefert ein erneutes <code>READ(Vehicle.Cabin.Seat.Position)</code> den final erreichten Endwert <code>100</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Semantik (Declarative vs. Imperative):</strong>\n<ul class=\"fig-list\"><li>Entwickler dürfen nach einem <code>UPDATE</code>-Aufruf nicht davon ausgehen, dass ein unmittelbar folgendes <code>READ</code> den neuen Wert liefert. <code>UPDATE</code> steuert den Sollwert (Actuator Target), während <code>READ</code> den physischen Istwert des Sensors/Aktuators spiegelt.\n</li></ul>\n</li><li><strong>Polling vs. Event-Driven (Pub/Sub):</strong>\n<ul class=\"fig-list\"><li>Das Schaubild zeigt Polling via wiederholte <code>READ</code>-Operationen. In produktiven AUTOSAR AP / VISS-Implementierungen ist für solche Übergänge vorzugsweise der Publish/Subscribe-Mechanismus (<code>SUBSCRIBE</code>/Notifications oder <code>ara::com</code>-Events) zu nutzen, um Buslast und CPU-Overhead durch zyklische Reads zu vermeiden.\n</li></ul>\n</li><li><strong>Zustandsmodellierung &amp; Timeouts:</strong>\n<ul class=\"fig-list\"><li>Applikationen müssen Latenzen, unvollständige Verfahrwege (z. B. Klemmschutz, Blockade, Abbruch) und Timeouts vorsehen. Erreicht der Istwert den deklarierten Sollwert innerhalb eines systemspezifischen Zeitfensters nicht, muss ein Fehlerzustand (z. B. via Diagnostic Event Manager / Dem oder Applikationslogik) behandelt werden.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-af75ca5dc65eb876", "to": "FIG-05f5e8fcaaf15855", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
